        {
          "title": "自愿签署知情同意书、良好沟通、理解和遵守研究要求",
          "expression": {
            "kind": "logical",
            "operator": "all",
            "children": [
              {
                "kind": "predicate",
                "predicate": {
                  "predicate_id": "IN01-c1-p1",
                  "subject": "参与者",
                  "attribute": "自愿签署知情同意书",
