                }
              },
              {
                "kind": "predicate",
                "predicate": {
                  "predicate_id": "IN01-c1-p2",
                  "subject": "参与者",
                  "attribute": "能够和研究者进行良好的沟通",
                  "comparator": "eq",
                  "value": true,
                  "source_clause": "能够和研究者进行良好的沟通"
                }
              },
              {
                "kind": "predicate",
                "predicate": {
                  "predicate_id": "IN01-c1-p3",
                  "subject": "参与者",
                  "attribute": "理解和遵守本研究的各项要求和限制条件",
                  "comparator": "eq",
                  "value": true,
                  "source_clause": "理解和遵守本研究的各项要求和限制条件"
                }
              }
            ]
          },
          "evidence_requirements": [
            {
              "fact_type": "知情同意书签署记录",
              "due_stage": "screening",
              "description": "需提供自愿签署的知情同意书（ICF）记录，并确认参与者能够与研究者良好沟通且理解研究要求。",
              "required_source_types": [
                "知情同意书"
              ]
            }
          ],
          "source_span_ids": [
            "phase3-acceptance-d001-ii-snapshot::body.p630"
          ],
          "source_excerpts": [
            "自愿签署知情同意书（Informed Consent Form，ICF），能够和研究者进行良好的沟通，并且理解和遵守本研究的各项要求和限制条件；"
          ]
        }
      ]
    },
    {
      "official_code": "IN-02",
      "components": [
        {
          "title": "签署ICF时年龄在18-75周岁（含）",
