                  "source_clause": "年龄≥18周岁"
                },
                "time_constraint": {
                  "anchor_type": "icf_date",
                  "direction": "on"
                }
              },
              {
                "kind": "predicate",
                "predicate": {
                  "predicate_id": "IN02-c1-p2",
                  "subject": "参与者",
                  "attribute": "年龄",
                  "comparator": "lte",
                  "value": 75,
                  "unit": "周岁",
                  "source_term": "年龄",
                  "source_clauses": [
                    "年龄≥18周岁且",
                    "≤75周岁"
                  ]
                },
                "time_constraint": {
                  "anchor_type": "icf_date",
                  "direction": "on"
                }
              }
            ]
          },
          "evidence_requirements": [
            {
              "fact_type": "年龄记录",
              "due_stage": "screening",
              "description": "需提供签署ICF时的年龄记录或出生日期，证明年龄≥18周岁且≤75周岁。",
