          ],
          "source_span_ids": [
            "phase3-acceptance-d001-ii-snapshot::body.p631"
          ],
          "source_excerpts": [
            "签署ICF时年龄≥18周岁且≤75周岁，性别不限；"
          ]
        }
      ]
    },
    {
      "official_code": "IN-03",
      "components": [
        {
          "title": "筛选时研究者评估斑块状银屑病、病史≥6个月且处于稳定期",
          "expression": {
            "kind": "logical",
            "operator": "all",
            "children": [
              {
                "kind": "predicate",
                "predicate": {
                  "predicate_id": "IN03-c1-p1",
