                  "attribute": "患有斑块状银屑病",
                  "comparator": "eq",
                  "value": true,
                  "requires_professional_judgment": true,
                  "source_clause": "由研究者评估患有斑块状银屑病"
                }
              },
              {
                "kind": "predicate",
                "predicate": {
                  "predicate_id": "IN03-c1-p2",
                  "subject": "参与者",
                  "attribute": "病史",
                  "comparator": "gte",
                  "value": 6,
                  "unit": "月",
                  "source_term": "病史",
                  "source_clause": "病史≥6个月",
                  "requires_professional_judgment": true
                }
              },
              {
                "kind": "predicate",
                "predicate": {
                  "predicate_id": "IN03-c1-p3",
                  "subject": "参与者",
                  "attribute": "处于稳定期",
                  "comparator": "eq",
                  "value": true,
                  "requires_professional_judgment": true,
                  "source_clause": "处于稳定期"
                }
              }
            ]
          },
          "evidence_requirements": [
            {
              "fact_type": "斑块状银屑病评估记录",
              "due_stage": "screening",
              "description": "需提供研究者对斑块状银屑病诊断、病史时长≥6个月及稳定期的评估记录。",
              "required_source_types": [
                "既往和现病史",
                "体格检查"
              ]
            }
          ],
          "source_span_ids": [
            "phase3-acceptance-d001-ii-snapshot::body.p632"
          ],
          "source_excerpts": [
            "筛选时，由研究者评估患有斑块状银屑病，病史≥6个月，且处于稳定期；"
          ]
        }
      ]
    }
  ]
